import { ACCESS_NARRATIVE, PHARMA_NARRATIVE, RETAIL_NARRATIVE, SAMPLE_NARRATIVE } from './sampleData';

/** Downloadable synthetic data kits (generated by scripts/generate-demo-data.ts into public/sample-data). */
